function Invoke-StockArticleVerification {
    if ($script:TestState) { $script:Actions.Add('stock-article-verification') | Out-Null; return }
    $output = Join-Path $EvidenceParent "$TrialId-stock-article-verification.json"
    $command = 'set -e; test "$(pi --version)" = 0.84.4; pi list | tr -d "\r" | grep -F "$HOME/git/agent-skills" >/dev/null; printf stock-article-ok'
    $arguments = @('--distribution','Debian2','--user','jack','--exec','/bin/bash','-lic',$command)
    $quoted = @($arguments | ForEach-Object { if ($_ -notmatch '[\s"]') { $_ } else { '"' + ([regex]::Replace($_, '(\\*)"', '$1$1\"') -replace '(\\+)$', '$1$1') + '"' } }) -join ' '
    $info = [Diagnostics.ProcessStartInfo]::new()
    $info.FileName = Join-Path $env:SystemRoot 'System32\wsl.exe'
    $info.Arguments = $quoted
    $info.UseShellExecute = $false
    $info.CreateNoWindow = $true
    $info.RedirectStandardOutput = $true
    $info.RedirectStandardError = $true
    $process = [Diagnostics.Process]::new()
    $process.StartInfo = $info
    if (-not $process.Start()) { throw 'Failed to start stock article verification.' }
    $stdoutTask = $process.StandardOutput.ReadToEndAsync()
    $stderrTask = $process.StandardError.ReadToEndAsync()
    $timedOut = -not $process.WaitForExit(45000)
    if ($timedOut) { $null = Start-Process (Join-Path $env:SystemRoot 'System32\taskkill.exe') -ArgumentList @('/PID',[string]$process.Id,'/T','/F') -Wait -PassThru -WindowStyle Hidden; $null = $process.WaitForExit(10000) }
    $streams = [Threading.Tasks.Task]::WaitAll(@($stdoutTask,$stderrTask),10000)
    $stdout = if($stdoutTask.IsCompleted){$stdoutTask.GetAwaiter().GetResult()}else{'<timeout>'}
    $stderr = if($stderrTask.IsCompleted){$stderrTask.GetAwaiter().GetResult()}else{'<timeout>'}
    Invoke-WslShutdown
    $result = [ordered]@{schema=1;arguments=$arguments;timedOut=$timedOut;streamsComplete=$streams;exitCode=$process.ExitCode;stdout=$stdout;stderr=$stderr;articleVhdxSha256=(Get-Sha256 $ArticleVhdx);completedUtc=[DateTime]::UtcNow.ToString('o')}
    [IO.File]::WriteAllText($output, ($result | ConvertTo-Json -Depth 8), [Text.UTF8Encoding]::new($false))
    if ($timedOut -or -not $streams -or $process.ExitCode -ne 0 -or -not $stdout.Contains('stock-article-ok')) { throw 'Retained article failed after stock restoration.' }
}

